import math
from mpmath import betainc, findroot
def tcdf(t, df):
    x = df / (df + t * t)
    p = 0.5 * betainc(df / 2.0, 0.5, 0, x, regularized=True)
    return float(1 - p if t > 0 else p)
def tinv(p, df):
    return float(findroot(lambda t: tcdf(t, df) - p, 2.0))
def ncdf(z):
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))
def zstar(p):
    return float(findroot(lambda z: ncdf(z) - p, 1.5))
def welch(s1, n1, s2, n2):
    a = s1 * s1 / n1; b = s2 * s2 / n2
    return math.sqrt(a + b), (a + b) ** 2 / (a * a / (n1 - 1) + b * b / (n2 - 1))
m1, s1, n1, m2, s2, n2 = 34, 8, 40, 30, 6, 45
md = m1 - m2
sd = math.sqrt(s1 ** 2 / n1 + s2 ** 2 / n2)
assert md == 4 and round(sd, 3) == 1.549
z = (0 - md) / sd
assert round(z, 2) == -2.58
p = ncdf(z)
assert round(p, 4) == 0.0049
tg = 0.8
n_ans = math.ceil((s1 ** 2 + s2 ** 2) / tg ** 2 - 1e-9)
assert n_ans == 157
assert math.sqrt((s1 ** 2 + s2 ** 2) / n_ans) <= tg < math.sqrt((s1 ** 2 + s2 ** 2) / (n_ans - 1))
print("ALL_CHECKS_PASSED")

